import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String discardLine = scanner.nextLine();
        String dataLine = scanner.nextLine();

        int maxLengthFound = 0;
        int totalTokensCount = 0;
        int currentPos = 0;
        int lastPos = 0;

        while (currentPos < dataLine.lastIndexOf(')')) {
            int startParen = dataLine.indexOf('(', currentPos);
            int endParen = dataLine.indexOf(')', startParen);
            String segment = dataLine.substring(lastPos, startParen);
            StringTokenizer tokenizer = new StringTokenizer(segment, "_");
            while (tokenizer.hasMoreTokens()) {
                int len = tokenizer.nextToken().length();
                if (len > maxLengthFound) maxLengthFound = len;
            }
            String insideContent = dataLine.substring(startParen + 1, endParen);
            StringTokenizer innerTokenizer = new StringTokenizer(insideContent, "_");
            while (innerTokenizer.hasMoreTokens()) {
                String token = innerTokenizer.nextToken();
                if (!token.isEmpty()) totalTokensCount++;
            }
            lastPos = endParen + 1;
            currentPos = endParen;
        }

        String remainingPart = dataLine.substring(lastPos);
        StringTokenizer remainingTokens = new StringTokenizer(remainingPart, "_");
        while (remainingTokens.hasMoreTokens()) {
            int len = remainingTokens.nextToken().length();
            if (len > maxLengthFound) maxLengthFound = len;
        }

        System.out.println(maxLengthFound + " " + totalTokensCount);
    }
