#include <iostream>
#include <string>
#include <sstream>

int main() {
    std::string discardLine, dataLine;
    std::getline(std::cin, discardLine);
    std::getline(std::cin, dataLine);

    int maxLengthFound = 0;
    int totalTokensCount = 0;
    size_t currentPos = 0;
    size_t lastPos = 0;

    while (true) {
        size_t startParen = dataLine.find('(', currentPos);
        if (startParen == std::string::npos) break;
        size_t endParen = dataLine.find(')', startParen);
        if (endParen == std::string::npos) break;

        std::string segment = dataLine.substr(lastPos, startParen - lastPos);
        std::istringstream segmentStream(segment);
        std::string token;

        while (std::getline(segmentStream, token, '_')) {
            if (token.length() > maxLengthFound) {
                maxLengthFound = token.length();
            }
        }

        std::string insideContent = dataLine.substr(startParen + 1, endParen - startParen - 1);
        std::istringstream insideStream(insideContent);
        while (std::getline(insideStream, token, '_')) {
            if (!token.empty()) {
                totalTokensCount++;
            }
        }

        lastPos = endParen + 1;
        currentPos = endParen + 1;
    }

    // Process remaining part after last parenthesis
    std::string remainingPart = dataLine.substr(lastPos);
    std::istringstream remainingStream(remainingPart);
    while (std::getline(remainingStream, token, '_')) {
        if (token.length() > maxLengthFound) {
            maxLengthFound = token.length();
        }
    }

    std::cout << maxLengthFound << " " << totalTokensCount << std::endl;
    return 0;
}
